/// <summary>
/// AVA
/// </summary>
/// <param name = "_prodTable">ProdTable</param>
public void initFromProdTable(ProdTable _prodTable)
{
    next initFromProdTable(_prodTable);

    InventDimId     inventDimId = this.InventDimId;
    InventDim       inventDim   = InventDim::find(inventDimId);

    if (isConfigurationkeyEnabled(configurationKeyNum(AVASCP)) && _prodTable.AVALicensePlateId)
    {
        inventDim.LicensePlateId = _prodTable.AVALicensePlateId;
        inventDim = inventDim::findOrCreate(inventDim);
        this.InventDimId = inventDim.InventDimId;
    }
}
